d tag' ), 'elite' => array( 'Per Tag: enable section', 'Selected tags', 'Badge content for each saved tag' ) ), 'placement' => 'settings', 'member_keys' => array( 'wcj_sale_flash_per_product_tag_enabled', 'wcj_sale_flash_per_product_tag_terms', 'wcj_sale_flash_per_product_tag[{term_id}]' ) ), array( 'module' => 'sale_flash', 'group' => 'sale_flash--product-editor', 'anchor' => 'booster-v10-s19-sale-flash-product-editor', 'label' => 'Set this product sale badge', 'consequence' => 'Enable a custom badge for this product and enter its HTML or shortcodes. Variations use their parent product for this choice.', 'context' => 'Confirm the badge on the product page and shop listing. Keep the original content before editing. Turn this product override off or restore its earlier content if needed; do not change its sale price just to change the badge.', 'guide' => 'https://booster.io/docs/woocommerce-sale-flash/#booster-v10-s19-sale-flash-product-editor', 'routes' => array( 'free' => array( 'post.php?post={product_id}&action=edit' ), 'plus' => array( 'post.php?post={product_id}&action=edit' ), 'elite' => array( 'post.php?post={product_id}&action=edit' ) ), 'members' => array( 'free' => array( 'Enable (Plus and Elite)', 'HTML (Plus and Elite)' ), 'plus' => array( 'Enable', 'HTML' ), 'elite' => array( 'Enable', 'HTML' ) ), 'placement' => 'product_editor', 'member_keys' => array( 'meta:wcj_sale_flash_enabled', 'meta:wcj_sale_flash' ) ), array( 'module' => 'sales_notifications', 'group' => 'sales_notifications--message', 'anchor' => 'booster-v10-s19-sales-notifications-message', 'label' => 'Choose the purchase details shown', 'consequence' => 'Notifications use order information. Message placeholders can reveal billing name, city and country as well as product and price. Purchased-time wording measures time since order creation, not payment. An image or message is not proof of a sale price.', 'context' => 'Review the exact details you intend to show publicly before enabling notifi