emplate_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=marketings&section=sales_notifications&active_tab=wcj_sales_template_tab' ) ), 'members' => array( 'free' => array( 'Display Screen (Elite only)', 'Display Position (Elite only)' ), 'plus' => array( 'Display Screen (Elite only)', 'Display Position (Elite only)' ), 'elite' => array( 'Display Screen', 'Display Position' ) ), 'placement' => 'settings', 'member_keys' => array( 'wcj_sale_msg_screen', 'wcj_sale_msg_position' ) ), array( 'module' => 'sales_notifications', 'group' => 'sales_notifications--appearance', 'anchor' => 'booster-v10-s19-sales-notifications-appearance', 'label' => 'Set notification appearance', 'consequence' => 'Set the width, colors and entrance and exit effects. These change the notification display, not the purchase information used.', 'context' => 'Check text contrast and whether the animation is distracting. Return to the previous size, colors or effects where editable, or switch notifications off if the message is difficult to read, especially on a narrow screen.', 'guide' => 'https://booster.io/docs/woocommerce-sales-notifications/#booster-v10-s19-sales-notifications-appearance', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=marketings&section=sales_notifications&active_tab=wcj_sales_styling_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=marketings&section=sales_notifications&active_tab=wcj_sales_styling_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=marketings&section=sales_notifications&active_tab=wcj_sales_styling_tab' ) ), 'members' => array( 'free' => array( 'Notifications Width (Elite only)', 'Background Color (Elite only)', 'Text Color (Elite only)', 'Display Effect (Elite only)', 'Hidden Effect (Elite only)' ), 'plus' => array( 'Notifications Width (Elite only)', 'Background Color (Elite only)', 'Text Color (Elite only)', 'Display Effect (Elite only)', 'Hidden Effect (Elite only)' ), 'elite' => array( 'Notifications Width', 'Background Color', 'Text Color', 'Display Effect', 'Hidden Effect' ) ), 'placement' => 'settings', 'member_keys' => array( 'wcj_sale_msg_styling[width]', 'wcj_sale_msg_styling[bgcolor]', 'wcj_sale_msg_styling[color]', 'wcj_sale_msg_styling[animation]', 'wcj_sale_msg_styling[hidden_animation]' ) ), array( 'module' => 'sales_notifications', 'group' => 'sales_notifications--timing', 'anchor' => 'booster-v10-s19-sales-notifications-timing', 'label' => 'Set notification timing', 'consequence' => 'Duration controls how long a notification stays visible; Next time display controls the interval used for another display. Existing repeat behavior can also affect whether another notification appears.', 'context' => 'Check one complete display cycle using test data. Restore the previous timing where editable, or switch notifications off if they interrupt shoppers. A quiet page can mean no eligible result, not a stopped store.', 'guide' => 'https://booster.io/docs/woocommerce-sales-notifications/#booster-v10-s19-sales-notifications-timing', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=marketings&section=sales_notifications&active_tab=wcj_sales_time_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=marketings&section=sales_notifications&active_tab=wcj_sales_time_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=marketings&section=sales_notifications&active_tab=wcj_sales_time_tab' ) ), 'members' => array( 'free' => array( 'Duration (seconds) (Elite only)', 'Next time display (seconds) (Elite only)' ), 'plus' => array( 'Duration (seconds) (Elite only)', 'Next time display (seconds) (Elite only)' ), 'elite' => array( 'Duration (seconds)', 'Next time display (seconds)' ) ), 'placement' => 'settings', 'member_keys' => array( 'wcj_sale_msg_duration', 'wcj_sale_msg_next' ) ), array( 'module' => 'sales_notifications', 'group' => 'sales_notifications--orders', 'anchor' => 'booster-v10-s19-sales-notifications-orders', 'label'