ons--redirect', 'anchor' => 'booster-v10-s19-url-coupons-redirect', 'label' => 'Choose where the shopper goes next', 'consequence' => 'After handling the coupon parameter, send the shopper to the current page without that parameter, the cart, checkout or a custom destination. A redirect does not prove that the coupon was accepted.', 'context' => 'Review the destination before sharing a link. Restore the previous destination if the link sends shoppers to an unintended page. Check coupon success separately from the destination. In Free, the Custom Local URL field can be edited but has no effect; Free returns to the current page without the coupon parameter.', 'guide' => 'https://booster.io/docs/woocommerce-url-coupons/#booster-v10-s19-url-coupons-redirect', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=url_coupons&active_tab=url_coupons_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=url_coupons&active_tab=url_coupons_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=url_coupons&active_tab=url_coupons_general_options_tab' ) ), 'members' => array( 'free' => array( 'Redirect URL (Plus and Elite)', 'Custom redirect URL (no effect in Free)' ), 'plus' => array( 'Redirect URL', 'Custom redirect URL' ), 'elite' => array( 'Redirect URL', 'Custom redirect URL' ) ), 'placement' => 'settings', 'member_keys' => array( 'wcj_url_coupons_redirect', 'wcj_url_coupons_redirect_custom_url' ) ), array( 'module' => 'url_coupons', 'group' => 'url_coupons--auto-add', 'anchor' => 'booster-v10-s19-url-coupons-auto-add', 'label' => 'Add products for fixed product coupons', 'consequence' => 'This option can add the coupon products to the cart before WooCommerce accepts or rejects the discount. It does not apply to every coupon type.', 'context' => 'Check the intended product list and coupon restrictions before sharing a link. Turn automatic additions off if you want shoppers to choose their products. Review any already-changed cart separately; switching this off does not empty it.', 'guide' => 'https://booster.io/docs/woocommerce-url-coupons/#booster-v10-s19-url-coupons-auto-add', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=url_coupons&active_tab=url_coupons_general_options_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=url_coupons&active_tab=url_coupons_general_options_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=url_coupons&active_tab=url_coupons_general_options_tab' ) ), 'members' => array( 'free' => array( '"Fixed product discount" Coupons (Plus and Elite)' ), 'plus' => array( '"Fixed product discount" Coupons' ), 'elite' => array( '"Fixed product discount" Coupons' ) ), 'placement' => 'settings', 'member_keys' => array( 'wcj_url_coupons_fixed_product_discount_add_products' ) ), array( 'module' => 'wishlist', 'group' => 'wishlist--single-button', 'anchor' => 'booster-v10-s19-wishlist-single-button', 'label' => 'Show a wishlist button on product page', 'consequence' => 'Choose whether to show the button, its title and its style where your edition allows changes. The button saves an item to a wishlist; it does not place an order.', 'context' => 'Check the saved and unsaved button states on product page. Turn this placement off or restore its wording and style if it is confusing. Selecting an already-saved item can remove it again.', 'guide' => 'https://booster.io/docs/woocommerce-wishlist/#booster-v10-s19-wishlist-single-button', 'routes' => array( 'free' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=wishlist&active_tab=wcj_wishlist_single_tab' ), 'plus' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_checkout&section=wishlist&active_tab=wcj_wishlist_single_tab' ), 'elite' => array( 'admin.php?page=wcj-plugins&wcj-cat=cart_and_c